import rawCountries from './countries.json';
import { foldArabic } from '../extraction/text';

export interface Country {
  /** ISO 3166-1 alpha-2 (plus XK for Kosovo). */
  code: string;
  /** ISO 3166-1 alpha-3, as printed in passport MRZ. */
  alpha3: string;
  ar: string;
  en: string;
  /** Country calling code without "+", or null when the territory has none. */
  dial: string | null;
}

/** Sorted by Arabic name. Generated by scripts/generate-countries.mjs. */
export const COUNTRIES: readonly Country[] = rawCountries as Country[];

const byCode = new Map(COUNTRIES.map((c) => [c.code, c]));
const byAlpha3 = new Map(COUNTRIES.map((c) => [c.alpha3, c]));

/**
 * MRZ nationality codes that are not plain ISO alpha-3 codes (ICAO Doc 9303 part 3).
 * null means the code does not identify a country (stateless, refugee, UN, unspecified).
 */
const MRZ_SPECIAL_CODES: Record<string, string | null> = {
  D: 'DE',
  GBD: 'GB',
  GBN: 'GB',
  GBO: 'GB',
  GBP: 'GB',
  GBS: 'GB',
  RKS: 'XK',
  UNO: null,
  UNA: null,
  UNK: 'XK',
  XXA: null,
  XXB: null,
  XXC: null,
  XXX: null,
  XOM: null,
};

export function getCountry(code: string | null | undefined): Country | undefined {
  return code ? byCode.get(code) : undefined;
}

export function countryName(code: string | null | undefined): string {
  return getCountry(code)?.ar ?? '';
}

/** Resolves an MRZ nationality / issuing state code ("EGY", "D<<", "GBD") to an alpha-2 code. */
export function countryFromMrzCode(raw: string): string | null {
  const code = raw.replace(/</g, '');
  if (code in MRZ_SPECIAL_CODES) return MRZ_SPECIAL_CODES[code] ?? null;
  return byAlpha3.get(code)?.code ?? null;
}

const searchIndex = COUNTRIES.map((c) => ({
  country: c,
  keys: [foldArabic(c.ar), c.en.toLowerCase(), c.code.toLowerCase(), c.alpha3.toLowerCase()],
}));

/** Filters countries for the searchable nationality list (Arabic or English name, or code). */
export function searchCountries(query: string): Country[] {
  const q = foldArabic(query);
  if (!q) return [...COUNTRIES];
  const qNoArticle = q.replace(/^ال/, '');
  const starts: Country[] = [];
  const contains: Country[] = [];
  for (const { country, keys } of searchIndex) {
    if (keys.some((k) => k.startsWith(q) || k.replace(/^ال/, '').startsWith(qNoArticle))) starts.push(country);
    else if (keys.some((k) => k.includes(q))) contains.push(country);
  }
  return [...starts, ...contains];
}
